 [InitializeOnLoad]public static partial class AdvancedPresentationSetup
 {
  const string Root="Assets/Game/VFX/Combat/Advanced/",Stage="AssetStaging/VFXPhase2/";
  static AdvancedPresentationSetup(){EditorApplication.update+=Poll;}
  static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;foreach(var task in new[]{"Meshes","Presentation","WindSetup","ArtTuning","FinalPresentation","FireLighting"})if(File.Exists(Stage+task+".request")){File.Delete(Stage+task+".request");try{if(task=="FireLighting")FireLighting();else if(task=="FinalPresentation")FinalPresentation();else if(task=="ArtTuning"){var data=Library();data.smallBlastPositions=new[]{new Vector3(-3.6f,3.6f,.5f),new Vector3(.8f,6.2f,-.4f),new Vector3(3.6f,3.5f,-1)};EditorUtility.SetDirty(data);foreach(var file in new[]{"Explosion_14_8x8.tga","Explosion_30_8x8.tga"}){var importer=(TextureImporter)AssetImporter.GetAtPath(Root+"Textures/"+file);importer.maxTextureSize=4096;importer.SaveAndReimport();}AssetDatabase.SaveAssets();}else if(task=="Meshes")Meshes();else if(task=="WindSetup"){var data=Library();data.windCone=ImportedWind();EditorUtility.SetDirty(data);AssetDatabase.SaveAssets();}else Presentation();File.WriteAllText(Stage+task.ToLower()+".json","{\"passed\":true}");}catch(Exception e){File.WriteAllText(Stage+task.ToLower()+".json",e.ToString());Debug.LogException(e);}return;}}
  static T Load<T>(string path)where T:UnityEngine.Object=>AssetDatabase.LoadAssetAtPath<T>(Root+path);
  static Material Material(string name,string graph)
  {
   var shader=Load<Shader>("Graphs/"+graph+".shadergraph");if(!shader)throw new Exception("Missing shader "+graph);var mat=Load<Material>("Materials/"+name+".mat");if(!mat){mat=new Material(shader);AssetDatabase.CreateAsset(mat,Root+"Materials/"+name+".mat");}else mat.shader=shader;return mat;
  }
  static AdvancedCombatVFXLibrary Library()
  {
   Directory.CreateDirectory(Root+"Resources");var data=Load<AdvancedCombatVFXLibrary>("Resources/AdvancedCombatVFX.asset");if(!data){data=ScriptableObject.CreateInstance<AdvancedCombatVFXLibrary>();AssetDatabase.CreateAsset(data,Root+"Resources/AdvancedCombatVFX.asset");}return data;
  }
  static void ImportTextures()
  {
   foreach(var guid in AssetDatabase.FindAssets("t:Texture2D",new[]{Root+"Textures"})){var path=AssetDatabase.GUIDToAssetPath(guid);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.maxTextureSize=2048;importer.sRGBTexture=path.Contains("Explosion")||path.Contains("Smoke");importer.alphaIsTransparency=path.Contains("Explosion")||path.Contains("Smoke");importer.wrapMode=path.Contains("Explosion")||path.Contains("Smoke")?TextureWrapMode.Clamp:TextureWrapMode.Repeat;importer.SaveAndReimport();}
  }
  static Mesh UserWind()
  {
   var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Game/VFX/Combat/击中后溢气流.fbx").GetComponentInChildren<MeshFilter>().sharedMesh;var mesh=Load<Mesh>("DashWind_UserMesh.asset");if(mesh)return mesh;mesh=UnityEngine.Object.Instantiate(source);mesh.name="User supplied wind shell canonical +Z";float bottom=source.bounds.min.y,length=source.bounds.size.y;var vertices=source.vertices;var uv=source.uv;for(int i=0;i<vertices.Length;i++){var p=vertices[i];vertices[i]=new Vector3(p.x,p.z,p.y-bottom);uv[i]=new Vector2(uv[i].x,(p.y-bottom)/length);}mesh.vertices=vertices;mesh.uv=uv;for(int sub=0;sub<mesh.subMeshCount;sub++){var triangles=mesh.GetTriangles(sub);for(int j=0;j<triangles.Length;j+=3){int old=triangles[j+1];triangles[j+1]=triangles[j+2];triangles[j+2]=old;}mesh.SetTriangles(triangles,sub);}mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,Root+"DashWind_UserMesh.asset");return mesh;
  }
  static Mesh Ribbon(int index)
  {
   string path="WindRibbon_"+index+".asset";var existing=Load<Mesh>(path);if(existing)return existing;const int segments=24;var v=new Vector3[(segments+1)*2];var uv=new Vector2[v.Length];var tris=new int[segments*6];for(int i=0;i<=segments;i++){float t=i/(float)segments,angle=index*2.15f+t*(index==1?-1.4f:1.1f);float r=Mathf.Lerp(1.65f,.3f,t);var centre=new Vector3(Mathf.Cos(angle)*r,Mathf.Sin(angle)*r,Mathf.Lerp(.2f,4,t));var side=new Vector3(-Mathf.Sin(angle),Mathf.Cos(angle),0)*(.04f+.04f*Mathf.Sin(t*Mathf.PI));v[i*2]=centre-side;v[i*2+1]=centre+side;uv[i*2]=new Vector2(0,t);uv[i*2+1]=new Vector2(1,t);if(i<segments){int k=i*6;tris[k]=i*2;tris[k+1]=i*2+2;tris[k+2]=i*2+1;tris[k+3]=i*2+1;tris[k+4]=i*2+2;tris[k+5]=i*2+3;}}var mesh=new Mesh{name="Short asymmetric wind ribbon "+index};mesh.vertices=v;mesh.uv=uv;mesh.triangles=tris;mesh.RecalculateNormals();AssetDatabase.CreateAsset(mesh,Root+path);return mesh;
  }
  static void Overlay(AdvancedCombatVFXLibrary data)
  {
   var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Game/Player/Gauntlet/Prefabs/GauntletViewModel.prefab");var renderer=prefab.GetComponentInChildren<SkinnedMeshRenderer>(true);data.gauntletSource=renderer.sharedMesh;var prior=Load<Mesh>("Gauntlet_EnergyOverlay.asset");if(prior){data.gauntletOverlay=prior;return;}var source=renderer.sharedMesh;var weights=source.boneWeights;var sourceVertices=source.vertices;var normals=source.normals;var tangents=source.tangents;var uv=source.uv;var masks=new Color[weights.Length];
   Vector2 Bone(int index){if(index<0||index>=renderer.bones.Length)return Vector2.zero;string n=renderer.bones[index].name.ToLowerInvariant();if(n.Contains("mechanism"))return new Vector2(1,.25f);if(n.Contains("hand_l"))return new Vector2(.9f,.6f);if(n.Contains("thumb")||n.Contains("index")||n.Contains("middle")||n.Contains("pink")||n.Contains("ring"))return new Vector2(.7f,.85f);if(n.Contains("lowerarm")||n.Contains("twist_arm"))return new Vector2(.08f,.05f);return Vector2.zero;}
   for(int i=0;i<weights.Length;i++){var w=weights[i];var b=Bone(w.boneIndex0)*w.weight0+Bone(w.boneIndex1)*w.weight1+Bone(w.boneIndex2)*w.weight2+Bone(w.boneIndex3)*w.weight3;masks[i]=new Color(1,b.y,1,b.x);}
   var map=new Dictionary<int,int>();var ids=new List<int>();var triangles=new List<int>();var sourceTriangles=source.GetTriangles(0);for(int i=0;i<sourceTriangles.Length;i+=3){if(sourceTriangles.Skip(i).Take(3).All(x=>masks[x].a<.2f))continue;for(int j=0;j<3;j++){int original=sourceTriangles[i+j];if(!map.TryGetValue(original,out int id)){id=ids.Count;ids.Add(original);map[original]=id;}triangles.Add(id);}}
   var mesh=new Mesh{name="Hand and mechanism energy surface only",indexFormat=IndexFormat.UInt32};mesh.vertices=ids.Select(i=>sourceVertices[i]).ToArray();mesh.normals=ids.Select(i=>normals[i]).ToArray();if(tangents.Length==sourceVertices.Length)mesh.tangents=ids.Select(i=>tangents[i]).ToArray();mesh.uv=ids.Select(i=>uv[i]).ToArray();mesh.colors=ids.Select(i=>masks[i]).ToArray();mesh.boneWeights=ids.Select(i=>weights[i]).ToArray();mesh.bindposes=source.bindposes;mesh.triangles=triangles.ToArray();mesh.bounds=source.bounds;AssetDatabase.CreateAsset(mesh,Root+"Gauntlet_EnergyOverlay.asset");data.gauntletOverlay=mesh;File.WriteAllText(Stage+"overlay_mesh.json",JsonConvert.SerializeObject(new{sourceVertices=source.vertexCount,overlayVertices=mesh.vertexCount,triangles=triangles.Count/3},Formatting.Indented));
  }
  static void Meshes(){ImportTextures();UserWind();for(int i=0;i<3;i++)Ribbon(i);var data=Library();Overlay(data);data.energyMaterial=Material("M_WeaponSurfaceEnergy","SG_WeaponSurfaceEnergy");Material("M_DashWind","SG_DashWind_URP");Material("M_HeatHaze","SG_HeatHaze_URP");Material("M_ChromaticSphere","SG_ChromaticDistortion");EditorUtility.SetDirty(data);AssetDatabase.SaveAssets();}
  static GameObject Save(GameObject go,string name){try{return PrefabUtility.SaveAsPrefabAsset(go,Root+"Prefabs/"+name+".prefab");}finally{UnityEngine.Object.DestroyImmediate(go);}}
  static GameObject GPU(string name,string graph){var go=new GameObject(name);go.AddComponent<VisualEffect>().visualEffectAsset=Load<VisualEffectAsset>("Graphs/"+graph+".vfx");go.AddComponent<VFXGroundBinder>();return Save(go,name);}
  static Renderer MeshObject(Transform parent,string name,Mesh mesh,Material mat){var go=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer));go.transform.SetParent(parent,false);go.GetComponent<MeshFilter>().sharedMesh=mesh;var r=go.GetComponent<MeshRenderer>();r.sharedMaterial=mat;r.shadowCastingMode=ShadowCastingMode.Off;r.receiveShadows=false;return r;}
  static GameObject Chromatic()
  {
   var go=new GameObject("ChromaticSphere");var gpu=new GameObject("GPU refraction output");gpu.transform.SetParent(go.transform,false);var v=gpu.AddComponent<VisualEffect>();v.visualEffectAsset=Load<VisualEffectAsset>("Graphs/VFX_ChromaticSphere.vfx");var sphere=GameObject.CreatePrimitive(PrimitiveType.Sphere);sphere.name="Stable screen-refraction mesh";UnityEngine.Object.DestroyImmediate(sphere.GetComponent<Collider>());sphere.transform.SetParent(go.transform,false);var r=sphere.GetComponent<Renderer>();r.sharedMaterial=Load<Material>("Materials/M_ChromaticSphere.mat");r.shadowCastingMode=ShadowCastingMode.Off;var c=go.AddComponent<ChromaticWaveController>();c.gpu=v;c.meshCore=r;c.useGPU=false;return Save(go,"ChromaticSphere");
  }
  static GameObject Heat(bool loop)
  {
   var go=new GameObject(loop?"HeatHaze_Loop":"HeatHaze_Burst");var quad=GameObject.CreatePrimitive(PrimitiveType.Quad);quad.name="Upward heat air";UnityEngine.Object.DestroyImmediate(quad.GetComponent<Collider>());quad.transform.SetParent(go.transform,false);quad.transform.localPosition=Vector3.up*1.5f;quad.transform.localScale=new Vector3(2.4f,4,1);var r=quad.GetComponent<Renderer>();r.sharedMaterial=Load<Material>("Materials/M_HeatHaze.mat");r.shadowCastingMode=ShadowCastingMode.Off;var c=go.AddComponent<HeatHazeController>();c.surface=r;c.loop=loop;c.duration=2;c.opacity=.8f;if(!loop){var gpu=new GameObject("GPU rising heat");gpu.transform.SetParent(go.transform,false);c.gpu=gpu.AddComponent<VisualEffect>();c.gpu.visualEffectAsset=Load<VisualEffectAsset>("Graphs/VFX_HeatBurst.vfx");}return Save(go,go.name);
  }
  static GameObject Wind()
  {
   if(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Game/VFX/Combat/ReconstructedWindCone/Prefabs/风锥.prefab"))return ImportedWind();
   var go=new GameObject("DashWindCone");var mat=Load<Material>("Materials/M_DashWind.mat");var list=new List<Renderer>{MeshObject(go.transform,"User supplied pressure sleeve",Load<Mesh>("DashWind_UserMesh.asset"),mat)};for(int i=0;i<3;i++)list.Add(MeshObject(go.transform,"Short wind ribbon "+i,Load<Mesh>("WindRibbon_"+i+".asset"),mat));var gpu=new GameObject("GPU wind shell");gpu.transform.SetParent(go.transform,false);var effect=gpu.AddComponent<VisualEffect>();effect.visualEffectAsset=Load<VisualEffectAsset>("Graphs/VFX_DashWindCone.vfx");var c=go.AddComponent<DashWindConeController>();c.gpu=effect;c.shells=list.ToArray();c.useGPU=false;return Save(go,"DashWindCone");
  }
  static GameObject ImportedWind()
  {
   var go=new GameObject("ChargeWindCone");var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Game/VFX/Combat/ReconstructedWindCone/Prefabs/风锥.prefab");if(!source)throw new Exception("Missing user wind prefab");var child=(GameObject)PrefabUtility.InstantiatePrefab(source);child.transform.SetParent(go.transform,false);child.transform.localPosition=Vector3.zero;child.transform.localRotation=Quaternion.identity;var c=go.AddComponent<DashWindConeController>();c.prefabPlayback=child.GetComponent<WindConeFX.WindConeBurst>();c.duration=c.prefabPlayback.duration;c.shells=Array.Empty<Renderer>();var outer=child.GetComponentsInChildren<MeshFilter>().First(f=>f.name=="Outer wind shell");var inner=child.GetComponentsInChildren<MeshFilter>().First(f=>f.name=="Inner wind shell");float end=outer.transform.localPosition.z+outer.sharedMesh.bounds.max.z*outer.transform.localScale.z;var ip=inner.transform.localPosition;ip.z=end-inner.sharedMesh.bounds.max.z*inner.transform.localScale.z;inner.transform.localPosition=ip;c.tipLocal=go.transform.InverseTransformPoint(outer.transform.TransformPoint(new Vector3(0,0,outer.sharedMesh.bounds.max.z)));return Save(go,"ChargeWindCone");
  }
  static void Presentation()
  {
   var data=Library();data.smallExplosion=GPU("ExplosionSmallGPU","VFX_ExplosionSmall");data.finalExplosion=GPU("ExplosionFinalGPU","VFX_ExplosionFinal");data.blackSmoke=GPU("BlackSmokeGPU","VFX_BlackSmokeBurst");data.groundDust=GPU("GroundDustGPU","VFX_GroundDustBurst");data.rubble=GPU("ConcreteRubbleGPU","VFX_ConcreteRubbleBurst");data.crystalShatter=GPU("CrystalShatterGPU","VFX_CrystalShatterGPU");data.trackDustGraph=Load<VisualEffectAsset>("Graphs/VFX_TrackDust.vfx");data.chromaticSphere=Chromatic();data.heatLoop=Heat(true);data.heatBurst=Heat(false);data.windCone=Wind();
   var steam=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Game/VFX/Combat/TankSteam.prefab"));steam.name="TankSteamAdvanced";var old=steam.transform.Find("Heat refraction");if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);foreach(var t in steam.GetComponentsInChildren<Transform>(true))if(t.name=="Cube"&&t.GetComponent<BoxCollider>())UnityEngine.Object.DestroyImmediate(t.gameObject);var heat=(GameObject)PrefabUtility.InstantiatePrefab(data.heatLoop);heat.transform.SetParent(steam.transform,false);heat.transform.localScale=Vector3.one*.45f;data.tankSteam=Save(steam,"TankSteamAdvanced");
   var sparksPath="Assets/Game/VFX/Combat/Sparks.prefab";if(!File.Exists(Stage+"Sparks_BeforePhase2.prefab"))File.Copy(sparksPath,Stage+"Sparks_BeforePhase2.prefab");var spark=PrefabUtility.LoadPrefabContents(sparksPath);try{foreach(var v in spark.GetComponentsInChildren<VisualEffect>())v.visualEffectAsset=Load<VisualEffectAsset>("Graphs/VFX_SparksFine.vfx");foreach(var r in spark.GetComponentsInChildren<ParticleSystemRenderer>())r.enabled=false;PrefabUtility.SaveAsPrefabAsset(spark,sparksPath);}finally{PrefabUtility.UnloadPrefabContents(spark);}
   var pipeline=AssetDatabase.LoadAssetAtPath<UnityEngine.Rendering.Universal.UniversalRenderPipelineAsset>("Assets/Game/Settings/PC_RPAsset.asset");var serialized=new SerializedObject(pipeline);serialized.FindProperty("m_OpaqueDownsampling").intValue=0;serialized.ApplyModifiedPropertiesWithoutUndo();EditorUtility.SetDirty(pipeline);
   var audio=AssetDatabase.FindAssets("t:AudioClip").Select(AssetDatabase.GUIDToAssetPath).FirstOrDefault(p=>Path.GetFileNameWithoutExtension(p).ToLower().Contains("explosion")&&!p.Contains("Big"));if(audio!=null)data.smallExplosionAudio=AssetDatabase.LoadAssetAtPath<AudioClip>(audio);EditorUtility.SetDirty(data);AssetDatabase.SaveAssets();
  }
